from __future__ import annotations

import re
from typing import Any, Callable

from ..download import is_model_installed, model_local_path

ProgressCb = Callable[[dict[str, Any]], None]

_CACHE: dict[str, Any] = {}

# Marian / Opus-MT positional embeddings are typically 512. Stay under that.
_MAX_SRC_TOKENS = 450
# CT2/HF batch size for cue-level translation (throughput vs peak memory).
_BATCH_SIZE = 32
# Small beam helps colloquial JA→ZH without much slowdown on short cues.
_BEAM_SIZE = 4


def _opus_compute_type(device: str) -> str:
    """Match Whisper-style quantized CT2 types for faster MT."""
    return "int8_float16" if str(device or "").startswith("cuda") else "int8"


def clear_model_cache() -> int:
    """Drop cached translators/tokenizers so GC + empty_cache can free VRAM."""
    n = len(_CACHE)
    _CACHE.clear()
    return n


def _load_opus(mt_model: str, device: str = "auto"):
    from ..device import resolve_ctranslate2_device

    try:
        from ..runtime_extras import ensure_mt

        ensured = ensure_mt()
        if not ensured.get("ok") and not ensured.get("skipped"):
            raise RuntimeError(
                ensured.get("message")
                or "Opus MT 运行库未就绪（需 ctranslate2 / transformers，下载翻译模型时会自动安装）"
            )
    except RuntimeError:
        raise
    except Exception:
        pass

    ct2_device = resolve_ctranslate2_device(device)
    try:
        from transformers import AutoTokenizer  # type: ignore
        import ctranslate2 as ct2  # type: ignore
    except ImportError as err:
        raise RuntimeError(
            "Opus MT requires ctranslate2 + transformers. "
            "Install with: pip install 'transub-engine[mt]'"
        ) from err

    if not is_model_installed(mt_model):
        raise RuntimeError(
            f"未安装翻译模型 {mt_model}。"
            f"请在「设置 → 环境 / 模型」下载后再开始生成（或改用已安装的 Opus / Sakura）。"
        )

    model_dir = str(model_local_path(mt_model))
    # Prefer CT2 converted dir if present; else try loading HF Marian via transformers generate
    ct2_dir = model_local_path(mt_model) / "ct2"
    if ct2_dir.exists():
        compute_type = _opus_compute_type(ct2_device)
        cache_key = f"{mt_model}:{ct2_device}:{compute_type}"
        if cache_key in _CACHE:
            return _CACHE[cache_key]
        translator = ct2.Translator(
            str(ct2_dir),
            device=ct2_device,
            compute_type=compute_type,
        )
        tokenizer = AutoTokenizer.from_pretrained(model_dir)
        pack = {
            "mode": "ct2",
            "translator": translator,
            "tokenizer": tokenizer,
            "device": ct2_device,
            "compute_type": compute_type,
        }
    else:
        cache_key = f"{mt_model}:{ct2_device}:hf"
        if cache_key in _CACHE:
            return _CACHE[cache_key]
        from transformers import MarianMTModel, MarianTokenizer  # type: ignore

        tokenizer = MarianTokenizer.from_pretrained(model_dir)
        model = MarianMTModel.from_pretrained(model_dir)
        # Marian defaults ship max_length=512; pairing it with max_new_tokens
        # floods logs with transformers UserWarning on every generate() call.
        if getattr(model, "generation_config", None) is not None:
            model.generation_config.max_length = None
            if getattr(model.generation_config, "max_new_tokens", None) is None:
                model.generation_config.max_new_tokens = 256
        # Honor job device for HF fallback path as well.
        if ct2_device == "cuda":
            try:
                import torch  # type: ignore

                if torch.cuda.is_available():
                    model = model.to("cuda")
            except Exception:
                pass
        pack = {"mode": "hf", "model": model, "tokenizer": tokenizer, "device": ct2_device}
    _CACHE[cache_key] = pack
    return pack


def _token_chunks(tokenizer: Any, text: str, max_tokens: int = _MAX_SRC_TOKENS) -> list[str]:
    """Split text into pieces that fit Marian's max source length."""
    raw = str(text or "").strip()
    if not raw:
        return []

    # Prefer splitting on sentence boundaries first (avoid encoding megabyte blobs at once).
    sentences = [
        p.strip()
        for p in re.split(r"(?<=[。！？!?．.])\s*|\n+", raw)
        if p and str(p).strip()
    ]
    if not sentences:
        sentences = [raw]

    chunks: list[str] = []
    buf = ""
    buf_len = 0
    for sent in sentences:
        sent_ids = tokenizer.encode(sent, add_special_tokens=False)
        sent_len = len(sent_ids)
        if sent_len > max_tokens:
            if buf:
                chunks.append(buf)
                buf, buf_len = "", 0
            for i in range(0, sent_len, max_tokens):
                piece_ids = sent_ids[i : i + max_tokens]
                chunks.append(tokenizer.decode(piece_ids, skip_special_tokens=True))
            continue
        if buf and buf_len + sent_len > max_tokens:
            chunks.append(buf)
            buf, buf_len = sent, sent_len
        else:
            buf = f"{buf}{sent}" if buf else sent
            buf_len += sent_len
    if buf:
        chunks.append(buf)
    return chunks or [raw]


def _join_parts(translated_parts: list[str]) -> str:
    joined = "".join(translated_parts)
    if translated_parts and all(
        any(ord(ch) < 128 and ch.isalpha() for ch in p[:8]) for p in translated_parts if p
    ):
        joined = " ".join(p.strip() for p in translated_parts if p.strip())
    return joined.strip()


def _translate_hf(model: Any, tokenizer: Any, text: str) -> str:
    import warnings

    parts = _token_chunks(tokenizer, text)
    translated_parts: list[str] = []
    model_device = None
    try:
        model_device = next(model.parameters()).device
    except Exception:
        model_device = None
    for part in parts:
        encoded = tokenizer(
            [part],
            return_tensors="pt",
            padding=True,
            truncation=True,
            max_length=_MAX_SRC_TOKENS,
        )
        if model_device is not None:
            encoded = {k: v.to(model_device) for k, v in encoded.items()}
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", UserWarning)
            generated = model.generate(
                **encoded,
                max_new_tokens=256,
                num_beams=_BEAM_SIZE,
            )
        translated_parts.append(
            tokenizer.batch_decode(generated, skip_special_tokens=True)[0]
        )
    return _join_parts(translated_parts)


def _translate_ct2(translator: Any, tokenizer: Any, text: str) -> str:
    parts = _token_chunks(tokenizer, text)
    translated_parts: list[str] = []
    for part in parts:
        tokens = tokenizer.convert_ids_to_tokens(
            tokenizer.encode(part, add_special_tokens=False)[:_MAX_SRC_TOKENS]
        )
        results = translator.translate_batch([tokens], beam_size=_BEAM_SIZE)
        out_tokens = results[0].hypotheses[0]
        translated_parts.append(
            tokenizer.decode(
                tokenizer.convert_tokens_to_ids(out_tokens),
                skip_special_tokens=True,
            )
        )
    return _join_parts(translated_parts)


def _translate_ct2_batch(translator: Any, tokenizer: Any, texts: list[str]) -> list[str]:
    """Batch many short cues; long cues still go through per-text chunking."""
    out: list[str] = [""] * len(texts)
    # Split into "simple" (fits one chunk) vs "long" (needs _token_chunks).
    simple_idx: list[int] = []
    simple_token_lists: list[list[str]] = []
    for i, text in enumerate(texts):
        raw = str(text or "").strip()
        if not raw:
            out[i] = ""
            continue
        ids = tokenizer.encode(raw, add_special_tokens=False)
        if len(ids) > _MAX_SRC_TOKENS:
            out[i] = _translate_ct2(translator, tokenizer, raw)
            continue
        simple_idx.append(i)
        simple_token_lists.append(tokenizer.convert_ids_to_tokens(ids))

    for start in range(0, len(simple_token_lists), _BATCH_SIZE):
        batch_tokens = simple_token_lists[start : start + _BATCH_SIZE]
        batch_idx = simple_idx[start : start + _BATCH_SIZE]
        results = translator.translate_batch(batch_tokens, beam_size=_BEAM_SIZE)
        for j, res in enumerate(results):
            out_tokens = res.hypotheses[0]
            out[batch_idx[j]] = tokenizer.decode(
                tokenizer.convert_tokens_to_ids(out_tokens),
                skip_special_tokens=True,
            ).strip()
    return out


def _translate_hf_batch(model: Any, tokenizer: Any, texts: list[str]) -> list[str]:
    import warnings

    out: list[str] = [""] * len(texts)
    model_device = None
    try:
        model_device = next(model.parameters()).device
    except Exception:
        model_device = None

    simple_idx: list[int] = []
    simple_texts: list[str] = []
    for i, text in enumerate(texts):
        raw = str(text or "").strip()
        if not raw:
            out[i] = ""
            continue
        ids = tokenizer.encode(raw, add_special_tokens=False)
        if len(ids) > _MAX_SRC_TOKENS:
            out[i] = _translate_hf(model, tokenizer, raw)
            continue
        simple_idx.append(i)
        simple_texts.append(raw)

    for start in range(0, len(simple_texts), _BATCH_SIZE):
        batch = simple_texts[start : start + _BATCH_SIZE]
        batch_idx = simple_idx[start : start + _BATCH_SIZE]
        encoded = tokenizer(
            batch,
            return_tensors="pt",
            padding=True,
            truncation=True,
            max_length=_MAX_SRC_TOKENS,
        )
        if model_device is not None:
            encoded = {k: v.to(model_device) for k, v in encoded.items()}
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", UserWarning)
            generated = model.generate(
                **encoded,
                max_new_tokens=256,
                num_beams=_BEAM_SIZE,
            )
        decoded = tokenizer.batch_decode(generated, skip_special_tokens=True)
        for j, text in enumerate(decoded):
            out[batch_idx[j]] = str(text or "").strip()
    return out


def opus_translate_cues(
    cues: list[dict[str, Any]],
    *,
    mt_model: str,
    device: str = "auto",
    language: str = "",
    on_progress: ProgressCb | None = None,
) -> list[dict[str, Any]]:
    from .ja_polish import (
        is_japanese_mt,
        is_nvv_only,
        map_nvv_to_zh,
        normalize_ja_cue,
        postprocess_zh,
        prepare_ja_for_mt,
        whole_cue_override,
    )

    pack = _load_opus(mt_model, device=device)
    dev_label = str(pack.get("device") or "cpu")
    polish_ja = is_japanese_mt(language)
    if on_progress:
        on_progress(
            {
                "stage": "translate",
                "percent": 1,
                "detail": f"机器翻译 {mt_model} · {dev_label}"
                + (" · 日语润色" if polish_ja else ""),
            }
        )

    total = max(len(cues), 1)
    out: list[dict[str, Any]] = [
        {"start": c.get("start"), "end": c.get("end"), "text": ""} for c in cues
    ]
    mode = pack["mode"]
    translator = pack.get("translator")
    model = pack.get("model")
    tokenizer = pack["tokenizer"]

    def _emit_progress(done: int) -> None:
        if not on_progress:
            return
        # ~20 ticks across the job so the MT progress band keeps advancing.
        step = max(1, total // 20)
        if done == 1 or done == total or done % step == 0:
            on_progress(
                {
                    "stage": "translate",
                    "percent": int(100.0 * done / total),
                    "detail": f"翻译 {done}/{total}",
                }
            )

    try:
        pending_idx: list[int] = []
        pending_text: list[str] = []
        pending_raw: list[str] = []

        def _flush() -> None:
            if not pending_idx:
                return
            if mode == "ct2":
                texts_out = _translate_ct2_batch(translator, tokenizer, pending_text)
            else:
                texts_out = _translate_hf_batch(model, tokenizer, pending_text)
            for j, idx in enumerate(pending_idx):
                zh = texts_out[j] if j < len(texts_out) else ""
                if polish_ja:
                    zh = postprocess_zh(pending_raw[j], zh)
                out[idx]["text"] = zh
                _emit_progress(idx + 1)
            pending_idx.clear()
            pending_text.clear()
            pending_raw.clear()

        for i, cue in enumerate(cues):
            text = str(cue.get("text") or "")
            if not text.strip():
                _emit_progress(i + 1)
                continue

            if polish_ja:
                override = whole_cue_override(text)
                if override is not None:
                    out[i]["text"] = override
                    _emit_progress(i + 1)
                    continue
                norm = prepare_ja_for_mt(text)
                if is_nvv_only(normalize_ja_cue(text)):
                    out[i]["text"] = map_nvv_to_zh(text)
                    _emit_progress(i + 1)
                    continue
                pending_idx.append(i)
                pending_text.append(norm)
                pending_raw.append(text)
            else:
                pending_idx.append(i)
                pending_text.append(text)
                pending_raw.append(text)

            if len(pending_idx) >= _BATCH_SIZE:
                _flush()
        _flush()
    except Exception as err:
        msg = str(err).lower()
        if "index out of range" in msg or isinstance(err, IndexError):
            raise RuntimeError(
                "机器翻译失败：源字幕过长或分段异常（Opus-MT 上限约 512 tokens）。"
                "已尝试自动分块；若仍失败请改用「仅转写」或 Advanced 智能翻译。"
                f" 详情: {err}"
            ) from err
        raise

    if on_progress:
        on_progress({"stage": "translate", "percent": 100, "detail": f"{len(out)} 条"})
    return out
